// 1. Recupera a resposta do Gemini e os dados originais do Webhook
const geminiOutput = $input.first().json.text;
const webhookBody = $('Webhook').first().json.body;

// 2. Valida os dados recebidos da coleta
if (!webhookBody || typeof webhookBody !== 'object') {
  throw new Error('Dados do Webhook não encontrados.');
}

const sourceName = webhookBody.source_name;
const externalId = webhookBody.external_id;
const sourceUrl = webhookBody.document_url || webhookBody.source_url;

if (typeof sourceName !== 'string' || !sourceName.trim()) {
  throw new Error('source_name não foi informado.');
}

if (typeof externalId !== 'string' || !externalId.trim()) {
  throw new Error('external_id não foi informado.');
}

if (typeof sourceUrl !== 'string' || !/^https?:\/\//i.test(sourceUrl)) {
  throw new Error('URL oficial do documento não foi informada ou é inválida.');
}

// 3. Interpreta o JSON retornado pelo Gemini
if (typeof geminiOutput !== 'string' || !geminiOutput.trim()) {
  throw new Error('O Gemini não retornou um texto válido.');
}

const cleanJson = geminiOutput
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/, '')
  .trim();

let parsed;

try {
  parsed = JSON.parse(cleanJson);
} catch {
  throw new Error('A resposta do Gemini não contém um JSON válido.');
}

// 4. Verifica o título obrigatório
if (
  typeof parsed.title?.value !== 'string' ||
  !parsed.title.value.trim()
) {
  throw new Error('Análise interrompida: o título do edital não foi identificado.');
}

// 5. Monta os metadados da fonte
const source = {
  source_name: sourceName.trim(),
  external_id: externalId.trim(),
  source_url: sourceUrl,
};

// 6. Converte evidências para source_references
const sourceReferences = [];

function getValue(field) {
  return field?.value ?? null;
}

function addReferences(fieldName, fieldData) {
  if (getValue(fieldData) === null) return;

  const evidence = fieldData?.evidence ?? [];

  if (!Array.isArray(evidence)) {
    throw new Error(`Evidências inválidas no campo: ${fieldName}`);
  }

  for (const item of evidence) {
    if (
      typeof item.excerpt !== 'string' ||
      !item.excerpt.trim() ||
      !['stated', 'inferred'].includes(item.basis)
    ) {
      throw new Error(`Evidência inválida no campo: ${fieldName}`);
    }

    const reference = {
      field: fieldName,
      document_url: sourceUrl,
      excerpt: item.excerpt.trim().slice(0, 500),
      basis: item.basis,
    };

    if (item.page != null) {
      reference.page = item.page;
    }

    if (item.section != null) {
      reference.section = item.section;
    }

    sourceReferences.push(reference);
  }
}

// 7. Campos principais
const fields = [
  'title',
  'institution',
  'opportunity_category',
  'objective',
  'observations',
  'opening_date',
  'closing_date',
  'target_audience',
  'eligible_locations',
  'required_documents',
  'funding_amount',
  'funding_currency',
  'counterpart_required',
];

const analysis = {};

for (const field of fields) {
  analysis[field] = getValue(parsed[field]);
  addReferences(field, parsed[field]);
}

analysis.analysis_summary = parsed.analysis_summary ?? null;

// 8. Critérios de elegibilidade
const requirementKeys = [
  'segments',
  'business_sizes',
  'organization_stages',
  'min_organization_age_months',
  'max_organization_age_months',
];

analysis.eligibility_criteria = {};

const omittedSegments = [];

for (const key of requirementKeys) {
  const fieldData = parsed.eligibility_criteria?.[key];
  let value = getValue(fieldData);

  // Validação determinística do limite de 100 caracteres
  if (key === 'segments' && value !== null) {
    if (!Array.isArray(value)) {
      throw new Error('eligibility_criteria.segments precisa ser uma lista.');
    }

    for (const segment of value) {
      if (typeof segment !== 'string') {
        throw new Error('Um dos segmentos retornados pelo Gemini não é um texto válido.');
      }
    }

    omittedSegments.push(
      ...value.filter(segment => segment.length > 100)
    );

    value = value.filter(segment => segment.length <= 100);
  }

  analysis.eligibility_criteria[key] = value;

  addReferences(`requirements.${key}`, fieldData);
}

// Registra os critérios omitidos em observations
if (omittedSegments.length > 0) {
  const note =
    `${omittedSegments.length} critério(s) de segmento foram omitidos ` +
    'da análise por ultrapassarem o limite técnico de 100 caracteres. ' +
    'A redação original deve ser verificada no edital.';

  if (analysis.observations === null) {
    analysis.observations = note;
  } else if (typeof analysis.observations === 'string') {
    analysis.observations = analysis.observations.trim()
      ? `${analysis.observations.trim()}\n\n${note}`
      : note;
  } else {
    throw new Error('observations precisa ser um texto ou null.');
  }
}

// 9. Informações ausentes
const missingInformation = parsed.missing_information ?? [];

if (!Array.isArray(missingInformation)) {
  throw new Error('missing_information precisa ser uma lista.');
}

analysis.missing_information = missingInformation;

// 10. Monta o payload para a API Node.js
const payload = {
  source,
  model_name: 'Gemini 3.5 Flash Lite',
  analyzed_at: new Date().toISOString(),
  analysis: {
    ...analysis,
    source_references: sourceReferences,
  },
};

// 11. Entrega o payload ao próximo node
return [{ json: payload }];
